-- 451: Original BrillaPrep WASSCE Core Mathematics sprint 2 beta questions, part 9 of 10 (batch wassce-core-math-sprint2-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_451_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_451_guard;
INSERT INTO _migration_451_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_041' AND NOT (q.topic_id IS 'topic_wassce_p2_math_prb' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A fair coin is tossed once. What is the probability of obtaining a tail?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 1/2","B. 1","C. 1/3","D. 1/4"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A fair coin has two equally likely outcomes, head and tail, so P(tail) = 1/2. Therefore the correct answer is A: 1/2.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_041' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_451_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_042' AND NOT (q.topic_id IS 'topic_wassce_p2_math_prb' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A bag contains 3 red balls and 7 blue balls. One ball is picked at random. What is the probability that it is red?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 3/7","B. 3/10","C. 7/10","D. 1/3"]' AND q.correct_answer IS 'B' AND q.explanation IS 'There are 3 red balls out of 3 + 7 = 10 equally likely balls, so P(red) = 3/10. (3/7 wrongly compares red to blue instead of red to the total; 7/10 is the probability of blue.) Therefore the correct answer is B: 3/10.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_042' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_451_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_043' AND NOT (q.topic_id IS 'topic_wassce_p2_math_prb' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A letter is chosen at random from the word MATHS. What is the probability that it is a vowel?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 2/5","B. 1/2","C. 1/5","D. 4/5"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The word MATHS has 5 letters and only one vowel (A), so P(vowel) = 1/5. (2/5 wrongly counts two vowels; only A qualifies.) Therefore the correct answer is C: 1/5.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_043' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_451_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_044' AND NOT (q.topic_id IS 'topic_wassce_p2_math_prb' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A fair die is thrown once. Find the probability of obtaining a number greater than 4.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 1/2","B. 2/3","C. 1/6","D. 1/3"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The outcomes greater than 4 are 5 and 6 — two of the six equally likely outcomes — so the probability is 2/6 = 1/3. (1/6 is the probability of one specific number.) Therefore the correct answer is D: 1/3.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_044' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_451_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_045' AND NOT (q.topic_id IS 'topic_wassce_p2_math_prb' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Two fair dice are thrown together. What is the probability of obtaining a double (both dice showing the same number)?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 1/6","B. 1/36","C. 1/12","D. 1/3"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Of the 6 × 6 = 36 equally likely outcomes, six are doubles: (1,1), (2,2), …, (6,6). Hence P(double) = 6/36 = 1/6. (1/36 is the probability of one specific double, such as (3,3).) Therefore the correct answer is A: 1/6.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_045' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_041', 'topic_wassce_p2_math_prb', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'A fair coin is tossed once. What is the probability of obtaining a tail?', 'multiple_choice', NULL, '["A. 1/2","B. 1","C. 1/3","D. 1/4"]', 'A', 'A fair coin has two equally likely outcomes, head and tail, so P(tail) = 1/2. Therefore the correct answer is A: 1/2.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO1', NULL, NULL, 'board_waec');
