INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_044', 'topic_wassce_p2_math_prb', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'A fair die is thrown once. Find the probability of obtaining a number greater than 4.', 'multiple_choice', NULL, '["A. 1/2","B. 2/3","C. 1/6","D. 1/3"]', 'D', 'The outcomes greater than 4 are 5 and 6 — two of the six equally likely outcomes — so the probability is 2/6 = 1/3. (1/6 is the probability of one specific number.) Therefore the correct answer is D: 1/3.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO1', NULL, NULL, 'board_waec');
